// Hand-written service worker (§6.1). Not generated by a plugin — we control
// all of it. No precaching for now (avoids serving a stale app after deploy).

self.addEventListener("install", () => {
  self.skipWaiting();
});

self.addEventListener("activate", (event) => {
  event.waitUntil(self.clients.claim());
});

self.addEventListener("push", (event) => {
  let data = {};
  try {
    data = event.data ? event.data.json() : {};
  } catch {
    data = { title: "The Threeball", body: event.data ? event.data.text() : "" };
  }
  event.waitUntil(
    self.registration.showNotification(data.title || "The Threeball", {
      body: data.body || "",
      icon: "/icons/icon-192.png",
      badge: "/icons/badge-72.png", // monochrome + transparent
      tag: data.tag, // same tag replaces rather than stacks
      data: { url: data.url || "/" },
      actions: data.actions || [], // Android only; iOS ignores these
    }),
  );
});

self.addEventListener("notificationclick", (event) => {
  event.notification.close();
  const url = event.notification.data && event.notification.data.url;
  event.waitUntil(
    clients
      .matchAll({ type: "window", includeUncontrolled: true })
      .then((list) => {
        const open = list.find((c) => c.url.includes(self.location.origin));
        if (open) return open.focus().then((c) => (c.navigate ? c.navigate(url) : c));
        return clients.openWindow(url || "/");
      }),
  );
});
